import { calculateDistance, formatDistance } from '~/entities/shop/lib/calculate-distance';
import type { GeolocationData } from '~/entities/shop/model/geolocation-model';
import type { Place } from '~/entities/shop/model/types';
import type { VoucherPlace } from '~/entities/voucher/api/dtos/voucher-item';
import i18n from '~/shared/i18n/i18n';

type GetVoucherMerchantListParams = {
  geolocation?: GeolocationData;
  shopList: Place[];
  voucherPlaces: VoucherPlace[];
};

const toCoordinate = (value: string | number | null | undefined) => {
  if (value === null || value === undefined || value === '') return null;
  const coordinate = Number(value);
  return Number.isFinite(coordinate) ? coordinate : null;
};

const getUnavailableLocationLabel = (geolocation?: GeolocationData) => {
  if (!geolocation) return i18n.t('common:checkingLocation');
  if (geolocation.failureReason === 'permission-denied') return i18n.t('common:notAllowedLocation');
  return i18n.t('common:notFoundLocation');
};

export const getVoucherMerchantList = ({
  geolocation,
  shopList,
  voucherPlaces,
}: GetVoucherMerchantListParams): VoucherPlace[] => {
  const shopsByPlaceId = new Map(shopList.flatMap((shop) => (shop.placeId ? ([[shop.placeId, shop]] as const) : [])));

  return voucherPlaces.map((voucherPlace) => {
    const shop = voucherPlace.placeId ? shopsByPlaceId.get(voucherPlace.placeId) : undefined;
    const latitude = toCoordinate(voucherPlace.latitude) ?? toCoordinate(shop?.latitude);
    const longitude = toCoordinate(voucherPlace.longitude) ?? toCoordinate(shop?.longitude);
    const hasCoordinates = latitude !== null && longitude !== null;
    const distanceLabel =
      geolocation?.position && hasCoordinates
        ? formatDistance(
            calculateDistance(geolocation.position.latitude, geolocation.position.longitude, latitude, longitude),
          )
        : getUnavailableLocationLabel(geolocation);

    return {
      ...voucherPlace,
      adres: shop?.adres ?? voucherPlace.adres,
      indutyInfo: shop?.indutyInfo ?? voucherPlace.indutyInfo,
      DISTANCE_NM: distanceLabel,
    };
  });
};
