import { useMemo } from 'react';
import { getVoucherMerchantList } from '~/pages/voucher/model/get-voucher-merchant-list';
import { useGeolocationQuery } from '~/entities/shop/model/geolocation-model';
import type { Place } from '~/entities/shop/model/types';
import type { VoucherPlace } from '~/entities/voucher/api/dtos/voucher-item';
import i18n from '~/shared/i18n/i18n';

type VoucherMerchantListProps = {
  shopList: Place[];
  voucherPlaces: VoucherPlace[];
};

export const VoucherMerchantList = ({ shopList, voucherPlaces }: VoucherMerchantListProps) => {
  const { data: geolocation } = useGeolocationQuery();
  const placeList = useMemo(
    () => getVoucherMerchantList({ geolocation, shopList, voucherPlaces }),
    [geolocation, shopList, voucherPlaces],
  );

  return (
    <div className="btm-sheet-filter2" data-testid="voucher-merchant-list" data-location-status={geolocation?.status}>
      <div className="shop-list">
        <p className="shop-cnt">{i18n.t('totalCount', { count: placeList.length })}</p>
        <div className="shop-list-inner">
          <ul>
            {placeList.map((item) => (
              <li key={item.placeId}>
                <div className="shop-list-box">
                  <h3>{item.placeNm}</h3>
                  <span className="shop-addr">
                    <b>{item.DISTANCE_NM}</b> <span className="shop-addr2">{item.adres}</span>
                  </span>
                  <span className="shop-type">
                    {item.indutyInfo && item.indutyInfo.length > 0 ? item.indutyInfo[0].indutyNm : ''}
                  </span>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};
