import { format } from 'date-fns';
import { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { VoucherMerchantList } from '~/pages/voucher/ui/voucher-merchant-list';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useGetShopListMutation } from '~/entities/shop/api/use-get-shop-list-mutation';
import type { Place } from '~/entities/shop/model/types';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { HistoryListContainer } from '~/entities/wallet/ui/wallet-history/history-list-container';
import { WalletSearchParamsProvider } from '~/entities/wallet/ui/wallet-history/wallet-search-params-provider';
import { VoucherType } from '~/shared/api/dtos/enums';
import { MAX_INPUT_NUMBER } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useShopBottomSheet } from '~/shared/lib/hooks/use-shop-bottom-sheet';
import { parseToDate } from '~/shared/lib/web-view-bridge';

export const VoucherDetailPage = () => {
  const { routerState } = useGetRouterState<{ vouchId: string }>();
  const { vouchId } = routerState;
  const { state } = useLocation();
  const { openShopBottomSheet } = useShopBottomSheet();
  const todayDate = format(new Date(), 'yyyyMMdd');
  const detail = (state ?? {}) as VoucherItemDTO;
  const [shopList, setShopList] = useState<Place[]>([]);
  const { mutateAsync: getShopList, isPending } = useGetShopListMutation();

  useEffect(() => {
    if (!state) return;
    let active = true;

    void getShopList().then((response) => {
      if (active) setShopList(response ?? []);
    });

    return () => {
      active = false;
    };
  }, [getShopList, state]);

  const fnFormattedAmount = (num?: string | number | null): string => {
    if (num === null || num === undefined || Number(num) < 0 || isNaN(Number(num))) return '';
    const numAmt = Number(num);
    if (numAmt > MAX_INPUT_NUMBER) {
      return MAX_INPUT_NUMBER.toLocaleString();
    }
    return numAmt.toLocaleString();
  };

  const handleOpenBottomSheet = () => {
    openShopBottomSheet({
      title: detail.vouchNm ?? '',
      description: i18n.t('availableMerchants'),
      children: <VoucherMerchantList shopList={shopList} voucherPlaces={detail.place ?? []} />,
    });
  };

  return (
    <>
      {isPending && <FullScreenLoading />}
      <div className="wrap bgw">
        <div className="content sub">
          <div
            className={`vouc-detail-area ${todayDate > parseToDate(detail.rcvfverUseEndDt, 'yyyyMMdd') ? 'exp' : ''} ${detail.type === VoucherType.모든_바우처 ? 'other' : ''}`}
          >
            <div className="vouc-detail-top">
              <p>{detail.vouchNm}</p>
              <span className="vouc-type cashback">{detail.vouchTyNm}</span>
            </div>
            <div className="vouc-balance">
              {i18n.t('balance')}
              <b>{fnFormattedAmount(detail.pbmBalanceOf ?? 0)}</b>
              {i18n.t('won')}
            </div>
            {todayDate > parseToDate(detail.rcvfverUseEndDt, 'yyyyMMdd') && (
              <span className="vouc-exp">{i18n.t('expired')}</span>
            )}
            <div className="vouc-detail-info">
              <dl>
                <dt>{i18n.t('voucherInfo')}</dt>
                <dd>
                  <span>{i18n.t('issuer')}</span>
                  <p>{detail.insttNm}</p>
                </dd>
                <dd>
                  <span>{i18n.t('usageConditions')}</span>
                  <p>{detail.pymntCond}</p>
                </dd>
                <dd>
                  <span>{i18n.t('issuedAmount')}</span>
                  <p>
                    {fnFormattedAmount(detail.pymntAmt ?? 0)}
                    {i18n.t('won')}
                  </p>
                </dd>
                <dd>
                  <span>{i18n.t('usagePeriod')}</span>
                  <p>
                    {parseToDate(detail.rcvfverUseStartDt, 'yyyy.MM.dd') +
                      ' ~ ' +
                      parseToDate(detail.rcvfverUseEndDt, 'yyyy.MM.dd')}
                  </p>
                </dd>
              </dl>
              <button type="button" className="chk-shop-btn" onClick={handleOpenBottomSheet}>
                {i18n.t('checkAvailableMerchants')}
              </button>
            </div>
          </div>
          {detail.type === VoucherType.내_바우처 && (
            <WalletSearchParamsProvider
              params={{
                vouchId,
                viewType: WalletHistoryViewType.HISTORY_HISTORY,
              }}
            >
              <h2 className="px-5 pb-5 pt-10">{i18n.t('recentVoucherUsageHistory')}</h2>
              <HistoryListContainer title={i18n.t('detail')} />
            </WalletSearchParamsProvider>
          )}
        </div>
        <div id="listMap" hidden></div>
      </div>
    </>
  );
};
